import sys
from itertools import product
from string import ascii_lowercase

def main():
    s = input().strip()
    t = input().strip()

    if len(s) != len(t):
        print("No such string")
        return

    if not (all(c.islower() for c in s) and all(c.islower() for c in t)):
        print("No such string")
        return

    if s >= t:
        print("No such string")
        return

    for mid in product(ascii_lowercase, repeat=len(s)):
        mid_str = ''.join(mid)
        if s < mid_str < t:
            print(mid_str)
            return

    print("No such string")

if __name__ == "__main__":
    main()
